mapper.select:
	select
	  	delayData.delaynum as delaynum,/*已延期*/
	   to_char(delayingData.mindate,'yyyy-mm-dd') as mindate,
	   to_char(delayingData.maxdate,'yyyy-mm-dd') as maxdate,
	   delayingData.delayingnum as delayingnum,/*即将延期*/
	   sendData.sendnum as sendnum,/*将报送*/
	   manualData.manualnum as manualnum,/*手工处理*/
	   interfPass.interfPassnum as interfPassnum,/*接口通过*/
	   interfBack.interfBacknum as interfBacknum,/*接口退回*/
	   deleteTemp.deletenum as deletenum,/*删除模版*/
	   deleteTemp.countType as countType,
	  	'14' as reporttype /*投资者身份信息*/
	  	FROM
	  	(select count(ces1.SUBMIT_STATUS) as delaynum from CHB_EQU_SUB  ces1 WHERE to_char(ces1.CHB_SUBMIT_DEADLINE,'yyyy-mm-dd') < to_char(#{searchDate,jdbcType=TIMESTAMP},'yyyy-mm-dd') and  ces1.SUBMIT_STATUS=#{NO_SUBMIT}


		#{item,jdbcType=VARCHAR}




	             #{item,jdbcType=VARCHAR}




	             #{item,jdbcType=VARCHAR}


	  	 ) delayData ,
	(select count(ces2.SUBMIT_STATUS) as delayingnum , min(ces2.SUBMIT_DEADLINE) as mindate, max(ces2.CHB_SUBMIT_DEADLINE) as maxdate from CHB_EQU_SUB  ces2 WHERE to_char(ces2.CHB_SUBMIT_DEADLINE,'yyyy-mm-dd') >= to_char(#{searchDate,jdbcType=TIMESTAMP},'yyyy-mm-dd') and to_char(ces2.SUBMIT_DEADLINE,'yyyy-mm-dd') <= to_char(#{searchDate,jdbcType=TIMESTAMP},'yyyy-mm-dd') and ces2.SUBMIT_STATUS=#{NO_SUBMIT} 


		#{item,jdbcType=VARCHAR}




	             #{item,jdbcType=VARCHAR}




	             #{item,jdbcType=VARCHAR}


	) delayingData,
	(select count(ces3.SUBMIT_STATUS) as sendnum from CHB_EQU_SUB  ces3 WHERE to_char(ces3.SUBMIT_DEADLINE,'yyyy-mm-dd') > to_char(#{searchDate,jdbcType=TIMESTAMP},'yyyy-mm-dd') and ces3.SUBMIT_STATUS=#{NO_SUBMIT}  


		#{item,jdbcType=VARCHAR}




	             #{item,jdbcType=VARCHAR}




	             #{item,jdbcType=VARCHAR}


	) sendData,
	(select count(ces3.SUBMIT_STATUS) as manualnum /*手工处理*/
	from CHB_EQU_SUB  ces3
	WHERE to_char(ces3.SUBMIT_TIME,'yyyy-mm-dd') = to_char(#{searchDate,jdbcType=TIMESTAMP},'yyyy-mm-dd')
	and ces3.SUBMIT_STATUS='03' /*手工处理*/


		#{item,jdbcType=VARCHAR}




	             #{item,jdbcType=VARCHAR}




	             #{item,jdbcType=VARCHAR}


	) manualData,
	(select count(ces3.SUBMIT_STATUS) as interfPassnum /*接口通过*/
	from CHB_EQU_SUB  ces3
    /***三期CHB_SUBMIT_STATUS去除改造  20220310**/
    /*left join CHB_SUBMIT_STATUS substatus
	 		on ces3.sumit_seq = substatus.seqno*/
    /***三期CHB_SUBMIT_STATUS去除改造  20220310**/
    WHERE to_char(ces3.SUBMIT_TIME,'yyyy-mm-dd') = to_char(#{searchDate,jdbcType=TIMESTAMP},'yyyy-mm-dd')
	and ces3.SUBMIT_STATUS='02' /*接口报送*/
	and ces3.SUBMIT_FEEDBACK_STATUS in ('01','03') /*发送成功，中债通过*/


		#{item,jdbcType=VARCHAR}




	             #{item,jdbcType=VARCHAR}




	             #{item,jdbcType=VARCHAR}


	) interfPass,
	(select count(ces3.SUBMIT_STATUS) as interfBacknum /*接口退回*/
	from CHB_EQU_SUB  ces3
    /***三期CHB_SUBMIT_STATUS去除改造  20220310**/
    /*left join CHB_SUBMIT_STATUS substatus
	 		on ces3.sumit_seq = substatus.seqno*/
    /***三期CHB_SUBMIT_STATUS去除改造  20220310**/
    WHERE to_char(ces3.SUBMIT_TIME,'yyyy-mm-dd') <= to_char(#{searchDate,jdbcType=TIMESTAMP},'yyyy-mm-dd') 
	and ces3.SUBMIT_STATUS='02' /*接口报送*/
	and ces3.SUBMIT_FEEDBACK_STATUS in ('02','04','05') /*接口退回*/


		#{item,jdbcType=VARCHAR}




	             #{item,jdbcType=VARCHAR}




	             #{item,jdbcType=VARCHAR}


	) interfBack,
	(SELECT
		count(1) as deletenum,
		'chbEquReg' as countType
	FROM
		CHB_EQU_SUB ces
	WHERE ces.STATUS='03' and ces.SUBMIT_STATUS='01'
	and to_char(ces.CHB_SUBMIT_DEADLINE,'yyyy-mm-dd') <= to_char(#{searchDate,jdbcType=TIMESTAMP},'yyyy-mm-dd')


		#{item,jdbcType=VARCHAR}




	             #{item,jdbcType=VARCHAR}




	             #{item,jdbcType=VARCHAR}


	         )deleteTemp

	select
  		delayData.delaynum as delaynum,/*已延期*/
