		left join CHB_EQUDET_SUBMIT_STATUS substatus
   		on ces3.sumit_seq = substatus.seqno
		WHERE to_char(ces3.SUBMIT_TIME,'yyyy-mm-dd') = to_char(#{searchDate,jdbcType=TIMESTAMP},'yyyy-mm-dd')
		and ces3.SUBMIT_STATUS='02' /*接口报送*/
		and substatus.SUBMIT_FEEDBACK_STATUS in ('01','03') /*发送成功，中债通过*/


