WITH prd_tmp AS ( SELECT
case when to_char(CHB_SUBMIT_DEADLINE, 'yyyy-mm-dd') < to_char(#{searchDate,jdbcType=TIMESTAMP}, 'yyyy-mm-dd') and SEND_STATUS=#{NO_SUBMIT} then '01' when to_char(CHB_SUBMIT_DEADLINE, 'yyyy-mm-dd') >= to_char(#{searchDate,jdbcType=TIMESTAMP}, 'yyyy-mm-dd') and to_char(CHB_SUBMIT_DEADLINE, 'yyyy-mm-dd') <= to_char(#{searchDate,jdbcType=TIMESTAMP}, 'yyyy-mm-dd') and SEND_STATUS=#{NO_SUBMIT} then '02' when to_char(CHB_SUBMIT_DEADLINE, 'yyyy-mm-dd') > to_char(#{searchDate,jdbcType=TIMESTAMP}, 'yyyy-mm-dd') and SEND_STATUS=#{NO_SUBMIT} then '03' when to_char(SUBMIT_TIME, 'yyyy-mm-dd') = to_char(#{searchDate,jdbcType=TIMESTAMP}, 'yyyy-mm-dd') and SEND_STATUS = '03' then '04' when to_char(SUBMIT_TIME, 'yyyy-mm-dd') = to_char(#{searchDate,jdbcType=TIMESTAMP}, 'yyyy-mm-dd') and SEND_STATUS = '02' /*接口报送*/ and SUBMIT_FEEDBACK_STATUS in ('01', '03') then '05' when to_char(SUBMIT_TIME, 'yyyy-mm-dd') <= to_char(#{searchDate,jdbcType=TIMESTAMP}, 'yyyy-mm-dd') and SEND_STATUS = '02' /*接口报送*/ and SUBMIT_FEEDBACK_STATUS in ('02', '04', '05') then '06' when DATA_STATUS = '03'and SEND_STATUS = '01' and to_char(CHB_SUBMIT_DEADLINE, 'yyyy-mm-dd') <= to_char(#{searchDate,jdbcType=TIMESTAMP}, 'yyyy-mm-dd') then '07' end SEND_STATUS, PR.SUBMIT_DEADLINE, PR.CHB_SUBMIT_DEADLINE FROM CHB_SALER_STL_DEAL_SUB PR WHERE 1=1
#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
)
SELECT SUM(DECODE(SEND_STATUS,'01',1,0)) as delaynum, /*已延期*/ min(DECODE(SEND_STATUS,'02',to_char(SUBMIT_DEADLINE, 'yyyy-mm-dd'),null)) as mindate, max(DECODE(SEND_STATUS,'02',to_char(CHB_SUBMIT_DEADLINE, 'yyyy-mm-dd'),null)) as maxdate, SUM(DECODE(SEND_STATUS,'02',1,0)) as delayingnum, /*即将延期*/ SUM(DECODE(SEND_STATUS,'03',1,0)) as sendnum, /*将报送*/ SUM(DECODE(SEND_STATUS,'04',1,0)) as manualnum, /*手工处理*/ SUM(DECODE(SEND_STATUS,'05',1,0)) as interfPassnum, /*接口通过*/ SUM(DECODE(SEND_STATUS,'06',1,0)) as interfBacknum, /*接口退回*/ null as deletenum,/*删除模版*/ null as countType, '35' as reporttype /*销售结算资金交易登记*/ FROM prd_tmp P

