WITH prd_tmp AS ( SELECT
SUBMIT_DEADLINE, CHB_SUBMIT_DEADLINE FROM CHB_SALER_INST_SUB WHERE 1=1
#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
)
SELECT SUM(DECODE(SEND_STATUS,'01',1,0)) as delaynum, /*已延期*/ min(DECODE(SEND_STATUS,'02',to_char(SUBMIT_DEADLINE, 'yyyy-mm-dd'),null)) as mindate, max(DECODE(SEND_STATUS,'02',to_char(CHB_SUBMIT_DEADLINE, 'yyyy-mm-dd'),null)) as maxdate, SUM(DECODE(SEND_STATUS,'02',1,0)) as delayingnum, /*即将延期*/ SUM(DECODE(SEND_STATUS,'03',1,0)) as sendnum, /*将报送*/ SUM(DECODE(SEND_STATUS,'04',1,0)) as manualnum, /*手工处理*/ SUM(DECODE(SEND_STATUS,'05',1,0)) as interfPassnum, /*接口通过*/ SUM(DECODE(SEND_STATUS,'06',1,0)) as interfBacknum, /*接口退回*/ null as deletenum, /*删除模版*/ null as countType, '42' as reporttype /*机构分支信息*/ FROM prd_tmp P

